describe('High-Tension Discharger mob skill',function()
 it('uses level-dependent Thunder breath caps, then gated Stun and cleanup',function()
  local discharge=require('scripts/actions/mobskills/high-tension_discharger');local move,process,effect=xi.mobskills.mobBreathMove,xi.mobskills.processDamage,xi.mobskills.mobStatusEffectMove;local params,damage,stun,deleted,localVar=nil,nil,nil,nil,nil;local level=64;local mob={getMainLvl=function()return level end,setLocalVar=function(_,key,value)localVar={key,value}end};local resistance=true;local target={takeDamage=function(_,...)damage={...}end,hasStatusEffect=function(_,effect)return resistance and effect==xi.effect.ELEMENTALRES_DOWN end,delStatusEffectSilent=function(_,effect)deleted=effect end};xi.mobskills.mobBreathMove=function(_,_,_,_,v)params=v;return {damage=123,attackType=xi.attackType.BREATH,damageType=xi.damageType.THUNDER}end;xi.mobskills.processDamage=function()return false end;xi.mobskills.mobStatusEffectMove=function(_,_,...)stun={...}end
  assert(discharge.onMobSkillCheck(target,mob,{})==0 and discharge.onMobWeaponSkill(mob,target,{},{})==123);assert(params.percentMultipier==.05 and params.damageCap==490 and params.bonusDamage==0 and params.mAccuracyBonus[1]==0 and params.mAccuracyBonus[2]==0 and params.mAccuracyBonus[3]==0 and params.resistStat==xi.mod.INT and params.element==xi.element.THUNDER and params.attackType==xi.attackType.BREATH and params.damageType==xi.damageType.THUNDER and params.shadowBehavior==xi.mobskills.shadowBehavior.IGNORE_SHADOWS and damage==nil and stun==nil and deleted==nil and localVar[1]=='nuclearWaste' and localVar[2]==0);level=65;discharge.onMobWeaponSkill(mob,target,{},{});assert(params.damageCap==750);xi.mobskills.processDamage=function()return true end;discharge.onMobWeaponSkill(mob,target,{},{})
  xi.mobskills.mobBreathMove,xi.mobskills.processDamage,xi.mobskills.mobStatusEffectMove=move,process,effect;assert(damage[1]==123 and damage[2]==mob and damage[3]==xi.attackType.BREATH and damage[4]==xi.damageType.THUNDER);assert(stun[1]==xi.effect.STUN and stun[2]==1 and stun[3]==3 and stun[4]==4 and deleted==xi.effect.ELEMENTALRES_DOWN)
 end)
end)
